-- Generate data for Order details table, for products ordered on Orders generated by "Generate Orders data" PL/SQL script
BEGIN
    FOR i IN 1..1350 LOOP 
        BEGIN 
            INSERT INTO OrderDetails (order_id,product_id,amount_ordered
            ) VALUES (
                -- For quick test data generation, pick a random combination of values for the 3 attributes
                TRUNC(DBMS_RANDOM.VALUE (70006,70656)),
                TRUNC(DBMS_RANDOM.VALUE (60001,60006)),
                TRUNC(DBMS_RANDOM.VALUE (1,6))
            );
        EXCEPTION
            -- if a unique constraint is violated by picking an already existing combination, handle the exception and continue the loop
            WHEN DUP_VAL_ON_INDEX THEN
                NULL;
        END;
    END LOOP;    
END;
/